def run(inputs: dict) -> dict:
    """
    Рассчитывает коэффициент вариации выручки:
    CV = (std / mean) * 100%
    """
    import numpy as np

    metrics = inputs.get("ExtractedMetric", [])
    if not metrics:
        raise ValueError("Нет входных данных ExtractedMetric")

    # Собираем значения выручки за FY 2020 и FY 2021
    values = {}
    for m in metrics:
        concept = m.get("concept")
        period = m.get("period_ref")
        scalar = m.get("scalar_fact", {})
        value = scalar.get("value")
        unit = scalar.get("unit")

        if concept != "SALES_REVENUE":
            continue
        if period not in ("FY 2020", "FY 2021"):
            continue
        if value is None:
            continue
        if unit != "млн. руб.":
            raise ValueError(f"Несовместимая единица измерения: {unit}")

        if period in values:
            raise ValueError(f"Дублирующееся значение для периода {period}")
        values[period] = value

    if "FY 2020" not in values or "FY 2021" not in values:
        raise ValueError(
            "Не хватает данных: нужны значения выручки за FY 2020 и FY 2021"
        )

    arr = np.array([values["FY 2020"], values["FY 2021"]])
    mean = np.mean(arr)
    if mean == 0:
        raise ValueError("Среднее значение равно нулю, CV не определён")

    cv = (np.std(arr, ddof=0) / mean) * 100.0
    return {"coefficient_of_variation": cv}
